import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageSquare, X, Shield, Zap } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const FloatingAssistant = () => {
    const [isOpen, setIsOpen] = React.useState(false);
    const navigate = useNavigate();

    return (
        <div className="fixed bottom-8 right-8 z-[100]">
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.8, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.8, y: 20 }}
                        className="mb-4 w-72 glass-card p-6 border-cyber-blue/30 shadow-[0_20px_50px_rgba(0,0,0,0.5)] bg-cyber-dark/95"
                    >
                        <div className="flex items-center gap-3 mb-4">
                            <div className="p-2 bg-cyber-blue/10 rounded-lg">
                                <Shield size={20} className="text-cyber-blue" />
                            </div>
                            <div>
                                <p className="text-xs font-black uppercase tracking-widest text-white">SafeNet AI</p>
                                <p className="text-[10px] text-green-400 font-bold uppercase">Online & Ready</p>
                            </div>
                        </div>

                        <p className="text-xs text-white/60 mb-6 leading-relaxed">
                            "I've detected some unusual activity in your network segment. Would you like to run a Phishing Scan?"
                        </p>

                        <div className="space-y-2">
                            <button
                                onClick={() => { navigate('/tool/phishing'); setIsOpen(false); }}
                                className="w-full py-2 bg-cyber-blue text-cyber-dark text-[10px] font-black uppercase rounded-lg hover:scale-105 transition-all"
                            >
                                Launch Scanner
                            </button>
                            <button
                                onClick={() => { navigate('/tool/chat'); setIsOpen(false); }}
                                className="w-full py-2 bg-white/5 border border-white/10 text-[10px] font-black uppercase rounded-lg hover:bg-white/10 transition-all text-white/70"
                            >
                                Ask Assistant
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all shadow-[0_0_20px_rgba(0,242,254,0.3)] hover:shadow-[0_0_30px_rgba(0,242,254,0.5)] group ${isOpen ? 'bg-white/10 scale-90' : 'bg-cyber-blue'}`}
            >
                {isOpen ? (
                    <X className="text-white" />
                ) : (
                    <div className="relative">
                        <MessageSquare className="text-cyber-dark group-hover:scale-110 transition-transform" />
                        <div className="absolute -top-1 -right-1 w-3 h-3 bg-[#EF4444] rounded-full border-2 border-cyber-blue animate-pulse"></div>
                    </div>
                )}
            </button>
        </div>
    );
};

export default FloatingAssistant;

import React, { useState } from 'react';
import { Shield, Bell, User, Search, Menu, Settings, Info } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const Navbar = ({ onMenuClick, onOpenProfile, onOpenSettings }) => {
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    return (
        <nav className="fixed top-0 left-0 right-0 h-16 glass-sidebar bg-transparent z-50 flex items-center justify-between px-6 border-b border-white/10 transition-all">
            {/* Logo Section */}
            <div className="flex items-center gap-4">
                <button onClick={onMenuClick} className="lg:hidden p-2 text-white/70 hover:text-white hover:bg-[#1E293B] rounded-md transition-colors">
                    <Menu size={20} />
                </button>
                <div className="flex items-center gap-2.5 cursor-pointer">
                    <div className="p-1.5 glass-btn-primary rounded-lg flex items-center justify-center">
                        <Shield size={20} className="text-white" />
                    </div>
                    <span className="text-lg font-bold text-white tracking-tight">
                        SafeNet-AI
                    </span>
                </div>
            </div>

            {/* Mid Section - Search */}
            <div className="hidden md:flex items-center flex-1 justify-center max-w-lg mx-auto px-8">
                <div className="relative w-full">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-white/50" />
                    <input
                        type="text"
                        placeholder="Search resources, threats, or documentation..."
                        className="w-full bg-[#1E293B] border border-[#334155] rounded-lg py-1.5 pl-9 pr-4 text-sm text-white focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-all placeholder:text-white/50"
                    />
                </div>
            </div>

            {/* Right Section - Utilities & Profile */}
            <div className="flex items-center gap-4">
                <button className="p-2 text-white/70 hover:text-white hover:bg-[#1E293B] rounded-lg relative transition-colors hidden sm:block">
                    <Bell size={18} />
                    <span className="absolute top-2 right-2 w-1.5 h-1.5 bg-blue-500 rounded-full border-2 border-slate-900"></span>
                </button>

                <div className="h-8 w-px bg-[#334155] hidden sm:block mx-1"></div>

                <div className="relative">
                    <div
                        className="flex items-center gap-3 cursor-pointer p-1 pr-2 hover:bg-[#1E293B] rounded-lg transition-colors"
                        onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                    >
                        <div className="w-8 h-8 rounded-full bg-[#334155] overflow-hidden border border-[#334155] flex items-center justify-center">
                            <User size={16} className="text-white/70" />
                        </div>
                        <div className="hidden xl:flex flex-col">
                            <span className="text-sm font-medium text-white leading-none mb-1">SafeNet Demo User</span>
                            <span className="text-[10px] text-white/50 uppercase tracking-wider font-semibold leading-none">Security Analyst</span>
                        </div>
                    </div>

                    {/* Dropdown Menu */}
                    <AnimatePresence>
                        {isDropdownOpen && (
                            <>
                                {/* Invisible overlay for outside click */}
                                <div
                                    className="fixed inset-0 z-40"
                                    onClick={() => setIsDropdownOpen(false)}
                                ></div>

                                <motion.div
                                    initial={{ opacity: 0, scale: 0.95 }}
                                    animate={{ opacity: 1, scale: 1 }}
                                    exit={{ opacity: 0, scale: 0.95 }}
                                    transition={{ duration: 0.15 }}
                                    className="absolute right-0 mt-2 w-[260px] rounded-xl bg-[#1F2937] border border-[#374151] shadow-[0_12px_30px_rgba(0,0,0,0.35)] z-50 overflow-hidden origin-top-right py-2"
                                >
                                    {/* User Header Section */}
                                    <div className="px-4 py-3 flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-full bg-[#3B82F6] flex items-center justify-center shrink-0">
                                            <span className="text-white font-bold text-lg">A</span>
                                        </div>
                                        <div className="flex flex-col overflow-hidden">
                                            <span className="text-sm font-bold text-[#E5E7EB] truncate">Admin User</span>
                                            <span className="text-xs text-[#9CA3AF] truncate">Workspace Owner</span>
                                        </div>
                                    </div>

                                    <div className="h-px bg-[#374151] w-full my-1"></div>

                                    {/* Menu Items */}
                                    <div className="px-2 py-1 space-y-1">
                                        <button
                                            className="w-full flex items-center gap-3 px-3.5 py-2.5 text-sm font-medium text-[#E5E7EB] hover:bg-[#374151] rounded-lg transition-colors"
                                            onClick={() => {
                                                setIsDropdownOpen(false);
                                                onOpenProfile();
                                            }}
                                        >
                                            <User size={16} />
                                            Profile
                                        </button>
                                        <button
                                            className="w-full flex items-center gap-3 px-3.5 py-2.5 text-sm font-medium text-[#E5E7EB] hover:bg-[#374151] rounded-lg transition-colors"
                                            onClick={() => {
                                                setIsDropdownOpen(false);
                                                onOpenSettings();
                                            }}
                                        >
                                            <Settings size={16} />
                                            Settings
                                        </button>
                                        <button
                                            className="w-full flex items-center gap-3 px-3.5 py-2.5 text-sm font-medium text-[#E5E7EB] hover:bg-[#374151] rounded-lg transition-colors"
                                            onClick={() => {
                                                setIsDropdownOpen(false);
                                            }}
                                        >
                                            <Info size={16} />
                                            About SafeNet-AI
                                        </button>
                                    </div>
                                </motion.div>
                            </>
                        )}
                    </AnimatePresence>
                </div>
            </div>
        </nav>
    );
};

export default Navbar;

import React, { useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, X, Shield, Mail, Calendar, Edit3 } from 'lucide-react';

const ProfileModal = ({ isOpen, onClose }) => {
    // Prevent scrolling when modal is open
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }
        return () => {
            document.body.style.overflow = 'unset';
        };
    }, [isOpen]);

    return (
        <AnimatePresence>
            {isOpen && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"
                    onClick={onClose}
                >
                    <motion.div
                        initial={{ scale: 0.95, opacity: 0, y: 10 }}
                        animate={{ scale: 1, opacity: 1, y: 0 }}
                        exit={{ scale: 0.95, opacity: 0, y: 10 }}
                        transition={{ type: "spring", duration: 0.3 }}
                        onClick={(e) => e.stopPropagation()}
                        className="bg-[#111827] border border-[#374151] rounded-2xl w-full max-w-sm overflow-hidden shadow-2xl relative"
                    >
                        {/* Header Background */}
                        <div className="h-24 bg-gradient-to-r from-blue-600 to-indigo-600 opacity-80"></div>

                        <button
                            onClick={onClose}
                            className="absolute top-4 right-4 p-1.5 bg-black/20 hover:bg-black/40 text-white rounded-full transition-colors"
                        >
                            <X size={18} />
                        </button>

                        <div className="px-6 pb-6 pt-0 relative">
                            {/* Avatar */}
                            <div className="flex justify-center -mt-12 mb-4">
                                <div className="w-24 h-24 bg-[#1F2937] border-4 border-[#111827] rounded-full flex items-center justify-center shadow-lg">
                                    <User size={40} className="text-[#E5E7EB]" />
                                </div>
                            </div>

                            {/* User Info */}
                            <div className="text-center mb-6">
                                <h2 className="text-2xl font-bold text-white mb-1">SafeNet Demo User</h2>
                                <div className="flex items-center justify-center gap-2 text-blue-400 font-medium text-sm mb-4">
                                    <Shield size={14} />
                                    <span>Security Analyst</span>
                                </div>
                            </div>

                            {/* Details List */}
                            <div className="space-y-3 mb-6 bg-[#1F2937] p-4 rounded-xl border border-[#374151]">
                                <div className="flex items-center gap-3 text-[#E5E7EB] text-sm">
                                    <Mail size={16} className="text-[#9CA3AF]" />
                                    <span>SafeNet-AI Demo Environment</span>
                                </div>
                                <div className="h-px bg-[#374151] w-full"></div>
                                <div className="flex items-center gap-3 text-[#E5E7EB] text-sm">
                                    <Calendar size={16} className="text-[#9CA3AF]" />
                                    <span>Last Login: Demo Mode</span>
                                </div>
                            </div>

                            {/* Action Button */}
                            <button className="w-full flex items-center justify-center gap-2 py-2.5 bg-[#3B82F6] hover:bg-[#2563EB] text-white font-medium rounded-xl transition duration-200">
                                <Edit3 size={16} />
                                Edit Profile
                            </button>
                        </div>
                    </motion.div>
                </motion.div>
            )}
        </AnimatePresence>
    );
};

export default ProfileModal;

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Settings, Shield, Bell, HardDrive, Download, Trash2, RotateCcw } from 'lucide-react';
import { useSettings } from '../contexts/SettingsContext';
import { useToast } from '../contexts/ToastContext';

// Reusable Toggle Switch Component
const ToggleSwitch = ({ checked, onChange }) => (
    <button
        type="button"
        onClick={onChange}
        className={`relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${checked ? 'bg-[#3B82F6]' : 'bg-[#374151]'
            }`}
    >
        <span
            className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${checked ? 'translate-x-5' : 'translate-x-0'
                }`}
        />
    </button>
);

const SettingsSection = ({ title, icon: Icon, children }) => (
    <div className="mb-8">
        <h3 className="flex items-center gap-2 text-[#E5E7EB] font-semibold mb-4 text-sm uppercase tracking-wider">
            <Icon size={16} className="text-[#9CA3AF]" />
            {title}
        </h3>
        <div className="bg-[#1F2937] border border-[#374151] rounded-xl overflow-hidden divide-y divide-[#374151]">
            {children}
        </div>
    </div>
);

const SettingsRow = ({ title, description, control }) => (
    <div className="flex items-center justify-between p-4 hover:bg-white/[0.02] transition-colors">
        <div className="pr-4">
            <p className="text-sm font-medium text-white mb-0.5">{title}</p>
            {description && <p className="text-xs text-[#9CA3AF] leading-relaxed">{description}</p>}
        </div>
        <div className="shrink-0 ml-4">
            {control}
        </div>
    </div>
);

const SettingsModal = ({ isOpen, onClose }) => {
    const { settings, toggleSetting, resetSettings, clearCache, exportLogs } = useSettings();
    const { addToast } = useToast();

    // Local state for the Mock 2FA Modal
    const [show2FAModal, setShow2FAModal] = useState(false);
    const [twoFactorCode, setTwoFactorCode] = useState('');

    const handle2FAToggle = () => {
        if (!settings.twoFactorAuth) {
            // Turning it ON: user needs to verify first
            setShow2FAModal(true);
        } else {
            // Turning it OFF: happens instantly
            toggleSetting('twoFactorAuth');
        }
    };

    const confirm2FA = () => {
        if (twoFactorCode.length >= 6) {
            setShow2FAModal(false);
            toggleSetting('twoFactorAuth');
            addToast("Two-Factor Authentication Enabled", "success");
            setTwoFactorCode('');
        } else {
            addToast("Please enter a 6-digit code", "error");
        }
    };

    // Prevent scrolling when modal is open
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }
        return () => {
            document.body.style.overflow = 'unset';
        };
    }, [isOpen]);

    return (
        <AnimatePresence>
            {isOpen && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm sm:p-6"
                    onClick={onClose}
                >
                    <motion.div
                        initial={{ scale: 0.95, opacity: 0, y: 10 }}
                        animate={{ scale: 1, opacity: 1, y: 0 }}
                        exit={{ scale: 0.95, opacity: 0, y: 10 }}
                        transition={{ type: "spring", duration: 0.3 }}
                        onClick={(e) => e.stopPropagation()}
                        className="bg-[#111827] border border-[#374151] rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden shadow-2xl flex flex-col"
                    >
                        {/* Header */}
                        <div className="flex items-center justify-between p-6 border-b border-[#374151] bg-[#111827] z-10">
                            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                                <Settings className="text-[#3B82F6]" size={24} />
                                Configuration Panel
                            </h2>
                            <button
                                onClick={onClose}
                                className="p-2 text-[#9CA3AF] hover:text-white hover:bg-[#1F2937] rounded-lg transition-colors"
                            >
                                <X size={20} />
                            </button>
                        </div>

                        {/* Scrollable Content */}
                        <div className="flex-1 overflow-y-auto p-6 scrollbar-hide">
                            <SettingsSection title="General Settings" icon={Settings}>
                                <SettingsRow
                                    title="Dark Mode"
                                    description="Apply system-wide dark styling to reduce eye strain."
                                    control={<ToggleSwitch checked={settings.darkMode} onChange={() => toggleSetting('darkMode')} />}
                                />
                                <SettingsRow
                                    title="Glass UI"
                                    description="Enable modern frosted glass styling and layer blurs."
                                    control={<ToggleSwitch checked={settings.glassUI} onChange={() => toggleSetting('glassUI')} />}
                                />
                            </SettingsSection>

                            <SettingsSection title="Security Settings" icon={Shield}>
                                <SettingsRow
                                    title="2-Factor Authentication"
                                    description="Require a secondary code for administrative actions."
                                    control={<ToggleSwitch checked={settings.twoFactorAuth} onChange={handle2FAToggle} />}
                                />
                                <SettingsRow
                                    title="Auto-Scan Suspicious URLs"
                                    description="Automatically trigger real-time reputation checks on clicked links."
                                    control={<ToggleSwitch checked={settings.autoScanURLs} onChange={() => toggleSetting('autoScanURLs')} />}
                                />
                                <SettingsRow
                                    title="Email Threat Detection"
                                    description="Integrate with mailbox to proactively scan incoming comms."
                                    control={<ToggleSwitch checked={settings.emailThreatDetection} onChange={() => toggleSetting('emailThreatDetection')} />}
                                />
                            </SettingsSection>

                            <SettingsSection title="Notifications" icon={Bell}>
                                <SettingsRow
                                    title="Critical Email Alerts"
                                    description="Receive immediate emails for critical system events."
                                    control={<ToggleSwitch checked={settings.criticalEmailAlerts} onChange={() => toggleSetting('criticalEmailAlerts')} />}
                                />
                                <SettingsRow
                                    title="Threat Alert Notifications"
                                    description="Show real-time toast notifications for detected threats."
                                    control={<ToggleSwitch checked={settings.threatNotifications} onChange={() => toggleSetting('threatNotifications')} />}
                                />
                                <SettingsRow
                                    title="Daily Security Summary"
                                    description="Receive a digest of blocked threats and system posture."
                                    control={<ToggleSwitch checked={settings.dailySummary} onChange={() => toggleSetting('dailySummary')} />}
                                />
                            </SettingsSection>

                            <SettingsSection title="System Operations" icon={HardDrive}>
                                <div className="p-4 flex flex-col sm:flex-row gap-3">
                                    <button
                                        onClick={clearCache}
                                        className="flex-1 flex items-center justify-center gap-2 py-2.5 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] text-white font-medium rounded-lg transition-colors text-sm"
                                    >
                                        <Trash2 size={16} className="text-red-400" />
                                        Clear Cache
                                    </button>
                                    <button
                                        onClick={() => {
                                            if (window.confirm("Are you sure you want to reset all data? This cannot be undone.")) {
                                                resetSettings();
                                            }
                                        }}
                                        className="flex-1 flex items-center justify-center gap-2 py-2.5 bg-[#1F2937] hover:bg-[#374151] border border-[#374151] text-white font-medium rounded-lg transition-colors text-sm"
                                    >
                                        <RotateCcw size={16} className="text-amber-400" />
                                        Reset Demo Data
                                    </button>
                                    <button
                                        onClick={exportLogs}
                                        className="flex-1 flex items-center justify-center gap-2 py-2.5 bg-[#3B82F6] hover:bg-[#2563EB] text-white font-medium rounded-lg transition-colors text-sm"
                                    >
                                        <Download size={16} />
                                        Export Logs
                                    </button>
                                </div>
                            </SettingsSection>
                        </div>
                    </motion.div>

                    {/* Mock 2FA Verification Modal overlay */}
                    <AnimatePresence>
                        {show2FAModal && (
                            <motion.div
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                                className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm"
                                onClick={() => setShow2FAModal(false)}
                            >
                                <motion.div
                                    initial={{ scale: 0.95, opacity: 0 }}
                                    animate={{ scale: 1, opacity: 1 }}
                                    exit={{ scale: 0.95, opacity: 0 }}
                                    onClick={(e) => e.stopPropagation()}
                                    className="bg-[#111827] border border-[#374151] rounded-2xl w-full max-w-sm p-6 shadow-2xl relative"
                                >
                                    <button onClick={() => setShow2FAModal(false)} className="absolute top-4 right-4 text-[#9CA3AF] hover:text-white">
                                        <X size={20} />
                                    </button>
                                    <div className="flex justify-center mb-4">
                                        <div className="p-3 bg-blue-500/10 rounded-full text-blue-500">
                                            <Shield size={32} />
                                        </div>
                                    </div>
                                    <h3 className="text-xl font-bold text-white text-center mb-2">Enable 2-Factor Auth</h3>
                                    <p className="text-sm text-[#9CA3AF] text-center mb-6">
                                        Enter the 6-digit code from your authenticator app to enable enhanced security.
                                    </p>
                                    <input
                                        type="text"
                                        value={twoFactorCode}
                                        onChange={(e) => setTwoFactorCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                        placeholder="000000"
                                        className="w-full bg-[#1F2937] border border-[#374151] rounded-lg py-3 px-4 text-center text-2xl tracking-[0.5em] font-mono text-white focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 mb-6"
                                    />
                                    <button
                                        onClick={confirm2FA}
                                        className="w-full py-3 bg-[#3B82F6] hover:bg-[#2563EB] text-white font-bold rounded-lg transition-colors"
                                    >
                                        Verify & Enable
                                    </button>
                                </motion.div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </motion.div>
            )}
        </AnimatePresence>
    );
};

export default SettingsModal;

import React from 'react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { ArrowRight } from 'lucide-react';

const ToolCard = ({ icon: Icon, title, description, link }) => {
    return (
        <motion.div
            whileHover={{ y: -4 }}
            transition={{ duration: 0.2 }}
            className="h-full"
        >
            <div className="glass-card p-6 shadow-lg flex flex-col h-full hover:bg-[#263449] hover:border-[#334155] transition-colors duration-200">
                <div className="flex items-center gap-4 mb-4">
                    <div className="p-3 bg-blue-500/10 text-[#2563EB] rounded-lg">
                        <Icon size={24} />
                    </div>
                    <h3 className="text-lg font-bold text-white">
                        {title}
                    </h3>
                </div>

                <p className="text-sm text-white/70 leading-relaxed mb-6 flex-1">
                    {description}
                </p>

                <Link
                    to={link}
                    className="inline-flex items-center justify-center gap-2 w-full glass-btn-primary mt-auto"
                >
                    <span>Open Tool</span>
                    <ArrowRight size={16} />
                </Link>
            </div>
        </motion.div>
    );
};

export default ToolCard;

import React, { createContext, useContext, useState, useEffect } from 'react';
import { useToast } from './ToastContext';

const SettingsContext = createContext(null);

const DEFAULT_SETTINGS = {
    darkMode: false,
    glassUI: true,
    twoFactorAuth: true,
    autoScanURLs: true,
    emailThreatDetection: false,
    criticalEmailAlerts: true,
    threatNotifications: true,
    dailySummary: false,
};

export const SettingsProvider = ({ children }) => {
    const [settings, setSettings] = useState(() => {
        // Hydrate from localStorage on initial load
        const stored = localStorage.getItem('safenet_settings');
        if (stored) {
            try {
                return JSON.parse(stored);
            } catch (e) {
                console.error("Failed to parse settings manually:", e);
                return DEFAULT_SETTINGS;
            }
        }
        return DEFAULT_SETTINGS;
    });

    const { addToast } = useToast();

    // Persist to localStorage whenever settings change
    useEffect(() => {
        localStorage.setItem('safenet_settings', JSON.stringify(settings));

        // Apply Global CSS Overrides
        if (settings.darkMode) {
            document.body.classList.add('dark-mode');
        } else {
            document.body.classList.remove('dark-mode');
        }

        if (!settings.glassUI) {
            document.body.classList.add('no-glass');
        } else {
            document.body.classList.remove('no-glass');
        }

    }, [settings]);

    const toggleSetting = (key) => {
        setSettings(prev => {
            const newValue = !prev[key];

            // Show toast feedback
            if (key === 'twoFactorAuth' && newValue) {
                // To be handled specifically by the component for the mock modal
            } else {
                const message = newValue ? `${formatKeyName(key)} enabled` : `${formatKeyName(key)} disabled`;
                addToast(message, newValue ? 'success' : 'info');
            }

            return {
                ...prev,
                [key]: newValue
            };
        });
    };

    const resetSettings = () => {
        setSettings(DEFAULT_SETTINGS);
        addToast("System reset completed. Demo defaults restored.", "success");
    };

    const clearCache = () => {
        localStorage.clear();
        // Keep current settings but commit them fresh
        localStorage.setItem('safenet_settings', JSON.stringify(settings));
        addToast("Cache successfully cleared", "success");
    };

    const exportLogs = () => {
        const payload = {
            timestamp: new Date().toISOString(),
            currentUser: "admin@safenet.ai",
            activeSettings: settings,
            systemHealth: "Optimal",
            recentThreatsBlocked: 42
        };

        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(payload, null, 2));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href", dataStr);
        downloadAnchorNode.setAttribute("download", "safenet_security_logs.json");
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();

        addToast("Security logs exported successfully", "success");
    };

    // Helper to make toast messages look nice (e.g. 'glassUI' -> 'Glass UI')
    const formatKeyName = (key) => {
        const names = {
            darkMode: "Dark Mode",
            glassUI: "Glass UI",
            twoFactorAuth: "Two-Factor Authentication",
            autoScanURLs: "Auto-Scan URLs",
            emailThreatDetection: "Email Threat Detection",
            criticalEmailAlerts: "Critical Email Alerts",
            threatNotifications: "Threat Notifications",
            dailySummary: "Daily Summary"
        };
        return names[key] || key;
    };

    return (
        <SettingsContext.Provider value={{
            settings,
            toggleSetting,
            resetSettings,
            clearCache,
            exportLogs
        }}>
            {children}
        </SettingsContext.Provider>
    );
};

export const useSettings = () => {
    const context = useContext(SettingsContext);
    if (!context) {
        throw new Error('useSettings must be used within a SettingsProvider');
    }
    return context;
};

import React, { createContext, useContext, useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { CheckCircle2, AlertTriangle, XCircle, Info, X } from 'lucide-react';

const ToastContext = createContext(null);

export const ToastProvider = ({ children }) => {
    const [toasts, setToasts] = useState([]);

    const removeToast = useCallback((id) => {
        setToasts(prev => prev.filter(toast => toast.id !== id));
    }, []);

    const addToast = useCallback((message, type = 'info', duration = 4000) => {
        const id = Date.now().toString() + Math.random().toString(36).substr(2, 9);
        setToasts(prev => [...prev, { id, message, type }]);

        if (duration > 0) {
            setTimeout(() => {
                removeToast(id);
            }, duration);
        }
    }, [removeToast]);

    const getIcon = (type) => {
        switch (type) {
            case 'success': return <CheckCircle2 size={20} className="text-green-400" />;
            case 'error': return <XCircle size={20} className="text-red-400" />;
            case 'warning': return <AlertTriangle size={20} className="text-amber-400" />;
            case 'info':
            default: return <Info size={20} className="text-blue-400" />;
        }
    };

    return (
        <ToastContext.Provider value={{ addToast, removeToast }}>
            {children}

            {/* Toast Container */}
            <div className="fixed top-20 right-6 z-[100] flex flex-col gap-3 w-full max-w-sm pointer-events-none">
                <AnimatePresence>
                    {toasts.map(toast => (
                        <motion.div
                            key={toast.id}
                            initial={{ opacity: 0, y: -20, scale: 0.95 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.95, transition: { duration: 0.2 } }}
                            className="bg-[#1F2937] border border-[#374151] shadow-2xl rounded-xl p-4 flex items-start gap-3 pointer-events-auto overflow-hidden relative"
                        >
                            {/* Accent Line */}
                            <div className={`absolute left-0 top-0 bottom-0 w-1 ${toast.type === 'success' ? 'bg-green-500' :
                                toast.type === 'error' ? 'bg-red-500' :
                                    toast.type === 'warning' ? 'bg-amber-500' : 'bg-blue-500'
                                }`} />

                            <div className="shrink-0 mt-0.5 ml-1">{getIcon(toast.type)}</div>
                            <div className="flex-1 pr-4">
                                <p className="text-sm font-medium text-white">{toast.message}</p>
                            </div>
                            <button
                                onClick={() => removeToast(toast.id)}
                                className="shrink-0 text-[#9CA3AF] hover:text-white transition-colors p-0.5 rounded-md hover:bg-white/10"
                            >
                                <X size={16} />
                            </button>
                        </motion.div>
                    ))}
                </AnimatePresence>
            </div>
        </ToastContext.Provider>
    );
};

export const useToast = () => {
    const context = useContext(ToastContext);
    if (!context) {
        throw new Error('useToast must be used within a ToastProvider');
    }
    return context;
};

