                            <Activity size={18} className="text-[#2563EB]" />
                            <h4 className="font-bold">Calculated Entropy</h4>
                        </div>
                        <div className="flex items-end gap-2">
                            <span className={`text-4xl font-bold leading-none ${entropy > 0 ? 'text-white' : 'text-slate-600'}`}>{entropy}</span>
                            <span className="text-xs font-bold text-white/70 uppercase tracking-widest pb-1">Bits</span>
                        </div>
                        <p className="text-sm text-white/70 leading-relaxed max-w-sm mt-4">
                            Entropy measures password unpredictability. Higher bit-entropy values exponentially increase the difficulty of guessing.
                        </p>
                    </div>

                    <div className="space-y-4 md:border-l md:border-slate-800 md:pl-8">
                        <div className="flex items-center gap-2 text-white mb-2">
                            <Zap size={18} className="text-[#2563EB]" />
                            <h4 className="font-bold">Estimated Crack Time</h4>
                        </div>
                        <div className="flex items-end gap-2 min-h-[40px]">
                            <span className={`text-2xl font-bold text-white leading-tight ${crackTime === 'N/A' ? 'text-slate-600' : 'text-white'}`}>
                                {crackTime}
                            </span>
                        </div>
                        <p className="text-sm text-white/70 leading-relaxed max-w-sm mt-4">
                            Estimated time to crack using a fast offline cluster computing at 1 billion guesses per second.
                        </p>
                    </div>
                </motion.div>

                {/* 4. AI Suggestions Card */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-transparent border border-[#334155] rounded-xl p-8 shadow-sm flex flex-col"
                >
                    <div className="flex items-center gap-3 mb-6">
                        <ChevronRight size={20} className="text-[#2563EB]" />
                        <h3 className="text-lg font-bold text-white">Improvement Suggestions</h3>
                    </div>

                    <AnimatePresence mode="wait">
                        {suggestions.length > 0 ? (
                            <div className="space-y-3 flex-1">
                                {suggestions.map((sugg, i) => (
                                    <motion.div
                                        key={i}
                                        initial={{ opacity: 0, y: 5 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: i * 0.1 }}
                                        className="flex gap-3 p-4 rounded-lg bg-[#1E293B] border border-[#334155]"
                                    >
                                        <div className="shrink-0 mt-0.5">
                                            <AlertTriangle size={16} className="text-[#F59E0B]" />
                                        </div>
                                        <p className="text-sm font-medium text-white leading-relaxed">
                                            {sugg}
                                        </p>
                                    </motion.div>
                                ))}
                            </div>
                        ) : (
                            <motion.div
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                className="flex flex-col items-center justify-center flex-1 text-center py-6"
                            >
                                <div className="p-4 rounded-full bg-[#22C55E]/10 mb-4 text-[#22C55E]">
                                    <Shield size={32} />
                                </div>
                                <p className="text-sm font-bold text-[#22C55E] mb-1">Password Optimal</p>
                                <p className="text-xs text-white/70">Excellent entropy and complexity detected.</p>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </motion.div>
            </div>
        </div>
    );
};

export default PasswordAnalyzer;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Search,
    ShieldAlert,
    ShieldCheck,
    Globe,
    AlertCircle,
    Cpu,
    Zap,
    Activity,
    MailWarning
} from 'lucide-react';
import { useSettings } from '../contexts/SettingsContext';
import { analyzePhishing } from '../services/mlEngine';

const PhishingDetector = () => {
    const { settings } = useSettings();
    const [input, setInput] = useState('');
    const [isScanning, setIsScanning] = useState(false);
    const [result, setResult] = useState(null);

    const scanContent = () => {
        if (!input.trim()) return;
        setIsScanning(true);
        setResult(null);

        // ML Engine NLP scan
        setTimeout(() => {
            const mlResult = analyzePhishing(input);

            let statusLabel = 'SECURE';
            if (mlResult.threatLevel === 'Critical') statusLabel = 'CRITICAL';
            else if (mlResult.threatLevel === 'Warning') statusLabel = 'WARNING';

            setResult({
                status: statusLabel,
                riskScore: mlResult.riskScore,
                signals: mlResult.detectedIndicators,
                indicators: [
                    { label: 'Keyword Heuristics', status: mlResult.threatLevel === 'Safe' },
                    { label: 'Semantic Threat Analysis', status: mlResult.threatLevel === 'Safe' },
                    { label: 'Cross-Vector Matching', status: mlResult.threatLevel === 'Safe' },
                    { label: 'Sender Reputation', status: mlResult.confidence > 80 }
                ],
                details: mlResult.recommendations.join(" ")
            });
            setIsScanning(false);
        }, 800);
    };

    // Simulate incoming message scan if Email Threat Detection is active
    React.useEffect(() => {
        if (!settings.emailThreatDetection) return;

        const timer = setTimeout(() => {
            if (!input && !isScanning && !result) {
                // Modified to trigger at least 3 indicators: urgency, credential harvesting, account suspension
                setInput("URGENT: Verify your account immediately or your account suspended within 24 hours. Login to confirm your identity at http://secure-login.xyz/auth");
                setTimeout(() => {
                    document.getElementById('phish-scan-btn')?.click();
                }, 500);
            }
        }, 3000); // Trigger 3 seconds after loading the page

        return () => clearTimeout(timer);
    }, [settings.emailThreatDetection]);

    return (
        <div className="space-y-6">
            {/* Header Section */}
            <header className="bg-transparent border border-[#334155] rounded-2xl p-8 flex items-center gap-6 shadow-sm">
                <div className="p-4 bg-blue-500/10 rounded-xl">
                    <MailWarning className="text-[#2563EB]" size={32} />
                </div>
                <div>
                    <h1 className="text-2xl font-bold text-white tracking-tight">
                        Phishing Detector
                    </h1>
                    <p className="text-white/70 text-sm mt-1">
                        Use advanced heuristics to analyze emails and messages for malicious intent.
                    </p>
                </div>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* 1. Content Input Card */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="lg:col-span-2 bg-transparent border border-[#334155] rounded-xl p-8 shadow-sm flex flex-col"
                >
                    <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-3">
                            <Search size={20} className="text-white/70" />
                            <h2 className="text-lg font-bold text-white">
                                Content Scanner
                            </h2>
                        </div>
                        {settings.emailThreatDetection && (
                            <div className="flex items-center gap-2 bg-green-500/10 px-3 py-1.5 rounded-full border border-green-500/20">
                                <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
                                <span className="text-xs font-semibold text-green-400">Real-time email monitoring active</span>
                            </div>
                        )}
                    </div>

                    <textarea
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        placeholder="Paste suspicious email content, messages, or text for analysis..."
                        className="w-full h-48 bg-[#1E293B] border border-[#334155] rounded-lg p-4 text-sm font-medium text-white focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-[#2563EB] transition-all placeholder:text-white/50 resize-none mb-6"
                    ></textarea>

                    <div className="flex items-center gap-4 mt-auto">
                        <button
                            id="phish-scan-btn"
                            onClick={scanContent}
                            disabled={isScanning || !input.trim()}
                            className={`px-8 py-3 rounded-lg font-semibold text-sm transition-all
                                ${isScanning || !input.trim()
                                    ? 'bg-[#1E293B] text-white/50 cursor-not-allowed border border-[#334155]'
                                    : 'glass-btn-primary text-white hover:bg-[#1D4ED8] shadow-lg shadow-blue-500/20'}`}
                        >
                            <span className="flex items-center gap-2">
                                {isScanning ? <><Cpu size={16} className="animate-spin" /> Scanning...</> : "Initiate Scan"}
                            </span>
                        </button>
                    </div>
                </motion.div>

                {/* 2. Results Indicator Card */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-transparent border border-[#334155] rounded-xl p-8 shadow-sm flex flex-col items-center justify-center text-center"
                >
                    <AnimatePresence mode="wait">
                        {!result && !isScanning ? (
                            <motion.div
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                className="flex flex-col items-center text-white/50"
                            >
                                <Globe size={48} className="mb-4 opacity-50" />
                                <p className="text-sm font-medium">Ready for input.</p>
                            </motion.div>
                        ) : isScanning ? (
                            <motion.div
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                className="flex flex-col items-center text-[#2563EB]"
                            >
                                <Cpu size={48} className="animate-spin mb-4" />
                                <p className="text-sm font-semibold">Analyzing Content...</p>
                            </motion.div>
                        ) : (
                            <motion.div
                                initial={{ opacity: 0, scale: 0.95 }}
                                animate={{ opacity: 1, scale: 1 }}
                                className="flex flex-col items-center w-full"
                            >
                                <div className={`w-32 h-32 rounded-full border-[6px] flex flex-col items-center justify-center mb-6
                                    ${result.status === 'SECURE' ? 'border-green-500' : 'border-red-500'}`}>
                                    <span className={`text-4xl font-bold leading-none ${result.status === 'SECURE' ? 'text-[#22C55E]' : 'text-[#EF4444]'}`}>
                                        {result.riskScore}
                                    </span>
                                    <span className="text-xs font-semibold text-white/70 mt-1 uppercase">Risk Score</span>
                                </div>
                                <div className={`w-full py-2 rounded-lg font-bold text-sm uppercase tracking-wider
                                    ${result.status === 'SECURE' ? 'bg-[#22C55E]/10 text-[#22C55E]' : 'bg-[#EF4444]/10 text-[#EF4444]'}`}>
                                    {result.status}
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </motion.div>

                {/* 3. Indicators Card */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="lg:col-span-2 bg-transparent border border-[#334155] rounded-xl p-8 shadow-sm grid grid-cols-1 md:grid-cols-2 gap-8"
                >
                    <div className="space-y-4">
                        <div className="flex items-center gap-2 text-white mb-4">
                            <Activity size={18} className="text-[#2563EB]" />
                            <h3 className="font-bold">Heuristic Validation</h3>
                        </div>
                        <div className="space-y-2">
                            {(result?.indicators || [
                                { label: 'Keyword Heuristics', status: null },
                                { label: 'Semantic Threat Analysis', status: null },
                                { label: 'Cross-Vector Matching', status: null },
                                { label: 'Sender Reputation', status: null }
                            ]).map((item, i) => (
                                <div key={i} className="flex items-center justify-between p-3 rounded-lg bg-[#1E293B] border border-[#334155]">
                                    <span className="text-xs font-semibold text-white">{item.label}</span>
                                    {item.status === null ? (
                                        <div className="w-4 h-0.5 bg-slate-600 rounded"></div>
                                    ) : item.status ? (
                                        <ShieldCheck size={16} className="text-[#22C55E]" />
                                    ) : (
                                        <ShieldAlert size={16} className="text-[#EF4444]" />
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-4 md:border-l md:border-slate-800 md:pl-8">
                        <div className="flex items-center gap-2 text-white mb-4">
                            <Zap size={18} className="text-[#2563EB]" />
                            <h3 className="font-bold">Analysis Output</h3>
                        </div>
                        <div className="p-4 rounded-lg bg-[#1E293B] border border-[#334155] h-[172px] overflow-y-auto">
                            <p className="text-sm font-medium text-white leading-relaxed">
                                {result ? result.details : <span className="text-white/50">Awaiting scan initiation to generate analysis report...</span>}
                            </p>
                        </div>
                    </div>
                </motion.div>

                {/* 4. Awareness Card */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-transparent border border-[#334155] rounded-xl p-8 shadow-sm flex flex-col"
                >
                    <div className="flex items-center gap-3 mb-6">
                        <AlertCircle size={20} className="text-[#2563EB]" />
                        <h3 className="text-lg font-bold text-white">Standard Protocols</h3>
                    </div>

                    <div className="space-y-4 flex-1">
                        <div className="flex gap-4 p-4 rounded-lg bg-[#1E293B] border border-[#334155]">
                            <div className="w-1.5 h-1.5 rounded-full bg-blue-500 mt-1.5 shrink-0"></div>
                            <div>
                                <h5 className="text-sm font-bold text-white mb-1">Verify Source</h5>
                                <p className="text-xs text-white/70 leading-relaxed">Cross-validate sender address with known contacts.</p>
                            </div>
                        </div>
                        <div className="flex gap-4 p-4 rounded-lg bg-[#1E293B] border border-[#334155]">
                            <div className="w-1.5 h-1.5 rounded-full bg-blue-500 mt-1.5 shrink-0"></div>
                            <div>
                                <h5 className="text-sm font-bold text-white mb-1">Avoid Links</h5>
                                <p className="text-xs text-white/70 leading-relaxed">Do not click on links in unsolicited messages.</p>
                            </div>
                        </div>
                    </div>
                </motion.div>

                {/* 5. Detected Indicators Card */}
                <AnimatePresence>
                    {result && result.signals && result.signals.length > 0 && (
                        <motion.div
                            initial={{ opacity: 0, height: 0, marginTop: 0 }}
                            animate={{ opacity: 1, height: 'auto', marginTop: 0 }}
                            exit={{ opacity: 0, height: 0 }}
                            transition={{ duration: 0.3 }}
                            className="lg:col-span-3 bg-[#1F2937] border border-[#374151] rounded-xl p-8 shadow-sm overflow-hidden"
                        >
                            <div className="flex items-center gap-3 mb-6">
                                <ShieldAlert size={20} className="text-[#EF4444]" />
                                <h3 className="text-lg font-bold text-[#E5E7EB]">Detected Indicators</h3>
                            </div>

                            <div className="flex flex-wrap gap-3">
                                {result.signals.map((indicator, idx) => (
                                    <motion.div
                                        key={idx}
                                        initial={{ opacity: 0, scale: 0.8 }}
                                        animate={{ opacity: 1, scale: 1 }}
                                        transition={{ duration: 0.25, delay: idx * 0.1 }}
                                        className="flex items-center gap-2 bg-[#374151] border border-[#4B5563] rounded-[6px] px-[10px] py-[6px]"
                                    >
                                        <AlertCircle size={14} className="text-[#F59E0B]" />
                                        <span className="text-[13px] text-[#E5E7EB] font-medium">{indicator}</span>
                                    </motion.div>
                                ))}
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </div>
    );
};

export default PhishingDetector;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Globe,
    ShieldCheck,
    ShieldAlert,
    Search,
    RefreshCw,
    ExternalLink,
    Activity,
    Fingerprint,
    Cpu,
    Server,
    Unlock,
    Navigation,
    Link as LinkIcon,
    Lock
} from 'lucide-react';
import { useSettings } from '../contexts/SettingsContext';
import { analyzeURL } from '../services/mlEngine';

const URLScanner = () => {
    const { settings } = useSettings();
    const [url, setUrl] = useState('');
    const [isScanning, setIsScanning] = useState(false);
    const [result, setResult] = useState(null);

    const scanURL = () => {
        if (!url.trim()) return;
        setIsScanning(true);
        setResult(null);

        // ML Engine random forest scan
        setTimeout(() => {
            const mlResult = analyzeURL(url);

            setResult({
                score: mlResult.riskScore,
                status: mlResult.threatLevel,
                details: mlResult.recommendations.join(" "),
                ip: "104.21.34." + Math.floor(Math.random() * 255),
                latency: Math.floor(Math.random() * 40 + 5) + "ms",
                indicators: [
                    { label: 'SSL Validation', status: mlResult.threatLevel === 'Safe' },
                    { label: 'Domain Reputation', status: mlResult.riskScore < 40 },
                    { label: 'Heuristic Match', status: mlResult.threatLevel !== 'Critical' },
                    { label: 'TLD Integrity', status: mlResult.riskScore < 50 }
                ],
                detectedIndicators: mlResult.detectedIndicators,
                confidence: mlResult.confidence
            });
            setIsScanning(false);
        }, 800);
    };

    const handlePaste = (e) => {
        const pastedContent = e.clipboardData.getData('Text');
        setUrl(pastedContent);

        if (settings.autoScanURLs && pastedContent.trim()) {
            setTimeout(() => {
                // We use a small timeout to let the state settle and simulate immediate auto-scan
                document.getElementById('scan-btn').click();
            }, 100);
        }
    };

    return (
        <div className="space-y-6">
            {/* Header Section */}
            <header className="bg-transparent border border-[#334155] rounded-2xl p-8 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 shadow-sm">
                <div className="flex items-center gap-6">
                    <div className="p-4 bg-blue-500/10 rounded-xl">
                        <LinkIcon className="text-[#2563EB]" size={32} />
                    </div>
                    <div>
                        <h1 className="text-2xl font-bold text-white tracking-tight">
                            URL Scanner
                        </h1>
                        <p className="text-white/70 text-sm mt-1">
                            Domain reputation, redirection chain analysis, and threat vector scanning.
                        </p>
                    </div>
                </div>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* 1. Entry Buffer Card */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="lg:col-span-2 bg-transparent border border-[#334155] rounded-xl p-8 shadow-sm flex flex-col justify-center relative overflow-hidden group"
                >
                    <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none">
                        <Navigation size={160} />
                    </div>

                    <div className="flex items-center justify-between mb-6 relative z-10">
                        <h2 className="text-lg font-bold text-white flex items-center gap-2">
                            <Search size={18} className="text-white/70" /> Target URL Analysis
                        </h2>
                        {settings.autoScanURLs && (
                            <span className="text-xs font-semibold text-blue-400 bg-blue-500/10 px-3 py-1 rounded-full border border-blue-500/20">
                                Auto security scan activated
                            </span>
                        )}
                    </div>

                    <div className="relative mb-6 z-10">
                        <input
                            type="text"
                            value={url}
                            onPaste={handlePaste}
                            onChange={(e) => setUrl(e.target.value)}
                            placeholder="https://example.com"
                            className="w-full bg-[#1E293B] border border-[#334155] rounded-lg p-4 text-sm text-white focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-[#2563EB] transition-all placeholder:text-white/50"
                        />
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-3 text-white/70">
                            <div className="h-5 w-px bg-slate-600"></div>
                            <Lock size={16} />
                        </div>
                    </div>

                    <div className="flex flex-col sm:flex-row gap-4 items-center z-10">
                        <button
                            id="scan-btn"
                            onClick={scanURL}
                            disabled={isScanning || !url.trim()}
                            className={`px-8 py-3 rounded-lg font-semibold text-sm transition-all focus:outline-none focus:ring-2 focus:ring-[#2563EB] focus:ring-offset-2 focus:ring-offset-slate-900 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2
                                ${isScanning || !url.trim() ? 'bg-[#1E293B] text-white/70 border border-[#334155]' : 'glass-btn-primary'}`}
                        >
                            {isScanning ? (
                                <>
                                    <RefreshCw size={16} className="animate-spin" />
                                    Scanning...
                                </>
                            ) : (
                                "Analyze URL"
                            )}
                        </button>
                    </div>
                </motion.div>

                {/* 2. Intensity Meter Card */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-transparent border border-[#334155] rounded-xl p-8 flex flex-col items-center justify-center text-center shadow-sm relative overflow-hidden min-h-[300px]"
                >
                    <AnimatePresence mode="wait">
                        {!result && !isScanning ? (
                            <motion.div
                                key="idle"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                                className="flex flex-col items-center"
                            >
                                <div className="w-16 h-16 rounded-full bg-[#1E293B] border border-[#334155] flex items-center justify-center mb-4">
                                    <Globe size={24} className="text-white/50" />
                                </div>
                                <p className="text-sm font-medium text-white/70">
                                    Awaiting input
                                </p>
                            </motion.div>
                        ) : isScanning ? (
                            <motion.div
                                key="scanning"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                                className="flex flex-col items-center"
                            >
                                <div className="relative w-20 h-20 mb-6">
                                    <div className="absolute inset-0 rounded-full border-4 border-slate-800 border-t-blue-500 animate-spin"></div>
                                    <div className="absolute inset-0 flex items-center justify-center">
                                        <Activity size={20} className="text-[#2563EB] animate-pulse" />
                                    </div>
                                </div>
                                <p className="text-sm font-semibold text-[#2563EB]">Analyzing domain...</p>
                            </motion.div>
                        ) : (
                            <motion.div
                                key="result"
                                initial={{ opacity: 0, scale: 0.95 }}
                                animate={{ opacity: 1, scale: 1 }}
                                className="flex flex-col items-center"
                            >
                                <div className={`w-32 h-32 rounded-full border-8 flex items-center justify-center mb-6 shadow-sm
                                    ${result.score > 70 ? 'border-red-500/20 text-[#EF4444] bg-[#EF4444]/5' : result.score > 30 ? 'border-orange-500/20 text-orange-500 bg-orange-500/5' : 'border-green-500/20 text-[#22C55E] bg-[#22C55E]/5'}`}>
                                    <div className="flex flex-col items-center">
                                        <span className="text-4xl font-bold tracking-tight">{result.score}</span>
                                        <span className="text-xs font-semibold uppercase tracking-wider opacity-80 mt-1">Risk Score</span>
                                    </div>
                                </div>
                                <h3 className={`text-sm font-bold uppercase tracking-wider px-4 py-1.5 rounded-full border
                                    ${result.status === 'Safe' ? 'text-[#22C55E] bg-[#22C55E]/10 border-green-500/20' : result.status === 'Critical' ? 'text-[#EF4444] bg-[#EF4444]/10 border-red-500/20' : 'text-orange-500 bg-orange-500/10 border-orange-500/20'}`}>
                                    {result.status}
                                </h3>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </motion.div>

                {/* 3. Detailed Matrix Card */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="lg:col-span-2 bg-transparent border border-[#334155] rounded-xl p-8 grid grid-cols-1 md:grid-cols-2 gap-8 shadow-sm"
                >
                    <div className="space-y-6">
                        <div className="flex items-center gap-3">
                            <Activity size={18} className="text-white/70" />
                            <h4 className="text-sm font-bold text-white">Security Checks</h4>
                        </div>
                        <div className="space-y-3">
                            {(result?.indicators || Array(4).fill({ label: 'Awaiting Scan...', status: null })).map((item, i) => (
                                <div key={i} className="flex items-center justify-between p-3 rounded-lg bg-[#1E293B] border border-[#334155]">
                                    <span className="text-sm font-medium text-white">{item.label}</span>
                                    {item.status === null ? (
                                        <div className="w-4 h-4 rounded-full border-2 border-[#334155] border-t-slate-400 animate-spin"></div>
                                    ) : item.status ? (
                                        <ShieldCheck size={18} className="text-[#22C55E]" />
                                    ) : (
                                        <ShieldAlert size={18} className="text-[#EF4444]" />
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-6 md:border-l md:border-slate-800 md:pl-8">
                        <div className="flex items-center gap-3">
                            <Server size={18} className="text-white/70" />
                            <h4 className="text-sm font-bold text-white">Server Details</h4>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="p-4 rounded-lg bg-[#1E293B] border border-[#334155] text-center">
                                <p className="text-xs font-semibold text-white/70 mb-1">IP Address</p>
                                <p className="text-sm font-bold text-white truncate">{result ? result.ip : "---.---.---.---"}</p>
                            </div>
                            <div className="p-4 rounded-lg bg-[#1E293B] border border-[#334155] text-center">
                                <p className="text-xs font-semibold text-white/70 mb-1">Latency</p>
                                <p className="text-sm font-bold text-white">{result ? result.latency : "--"}</p>
                            </div>
                        </div>
                        <div className="p-4 rounded-lg bg-[#1E293B] border border-[#334155] h-[100px] overflow-y-auto">
                            <p className="text-xs font-medium text-white/70 leading-relaxed">
                                {result ? result.details : "Scan details will appear here once the analysis is complete."}
                            </p>
                        </div>
                    </div>
                </motion.div>

                {/* 4. Infrastructure Metadata Card */}
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-transparent border border-[#334155] rounded-xl p-8 shadow-sm flex flex-col"
                >
                    <div className="flex items-center gap-3 mb-6">
                        <Fingerprint size={18} className="text-white/70" />
                        <h3 className="text-sm font-bold text-white">Verification Process</h3>
                    </div>

                    <div className="space-y-4 flex-1">
                        <div className="p-4 rounded-lg bg-[#1E293B] border border-[#334155]">
                            <h5 className="text-sm font-semibold text-white mb-1">SSL Certificate</h5>
                            <p className="text-xs text-white/70 leading-relaxed">Mandatory certificate signature verification against root CAs.</p>
                        </div>
                        <div className="p-4 rounded-lg bg-[#1E293B] border border-[#334155]">
                            <h5 className="text-sm font-semibold text-white mb-1">Reputation Engine</h5>
                            <p className="text-xs text-white/70 leading-relaxed">Cross-referencing domain history with global blacklists.</p>
                        </div>
                    </div>

                    <div className="mt-8 pt-6 border-t border-slate-800 flex items-center justify-between">
                        <p className="text-xs font-medium text-white/50">Scanner Engine v2.1</p>
                        <ShieldCheck size={16} className="text-slate-600" />
                    </div>
                </motion.div>
            </div>
        </div>
    );
};

export default URLScanner;
